      super(props)
      this.state = {
        items: [
          {
            id: 1,
            title: 'Chair',
            img:  'chair.jpeg',
            desc: 'Lorem ipsum dolor sit amet',
            category: 'chairs',
            price:'69.99'
          },
          {
            id: 2,
            title: 'sofa',
            img:  'sofa.jpeg',
            desc: 'Lorem ipsum dolor sit amet',
            category: 'sofas',
            price:'99.99'
          },
          {
            id: 3,
            title: 'Dining table',
            img:  'diningtable.',
            desc: 'Lorem ipsum dolor sit amet',
            category: 'chairs',
            price:'69.99'
          }
        ]
      }
    }

  render(){
       return (
            <div className="wrapper">
            <Header />
            <Footer />
            </div>
              );
          }
        }
export default App;
